/* colang.h — colang 编译器默认设置头（自动加载）
 *
 * 本头由编译器在**主翻译单元**预处理开始时自动注入（先于用户源文件展开，无需
 * `#include`），用于集中存放 colang 的「默认设置信息」——编译期缺省宏、约定开关、
 * 方言相关的默认定义等。后续新增的默认项直接写在此处即可对所有源生效。
 *
 * 边界与约定：
 *  - 仅注入主翻译单元；被 `import` 的库模块不重复注入（避免源合并时的符号/声明重复）。
 *  - 采用经典包含守卫：用户即便再显式 `#include <colang.h>` 也安全，不会二次展开。
 *  - 找不到本头（例如未随编译器附带 include/ 目录）时，编译器静默跳过、不影响既有行为。
 */
#ifndef _COLANG_H
#define _COLANG_H

/* 编译器标识：由 colang 编译时置 1，供源码 `#ifdef __COLANG__` 判别（类比 __clang__/__GNUC__）。 */
#define __COLANG__ 1

#endif /* _COLANG_H */
